oposal-pdf.php?token='.rawurlencode($token)))?>">Download PDF</a><?php if($proposal['payment_url']&&in_array($proposal['status'],['accepted','converted'],true)):?><a href="<?=e($proposal['payment_url'])?>" target="_blank" rel="noopener">Deposit link ↗</a><?php endif;?><a href="<?=e(app_url('call-dave.php'))?>">Call Us</a></div>
<?php if(in_array($proposal['status'],['sent','viewed'],true)):?><section class="proposal-response-section"><div class="proposal-accept-panel"><span>Approve proposal</span><h2>Ready to move forward?</h2><p><?=e($settings['acceptance_statement'])?></p><form method="post" action="<?=e(app_url('api/proposal-response.php'))?>" data-proposal-response-form><?=csrf_field()?><input type="hidden" name="action" value="accept"><input type="hidden" name="token" value="<?=e($token)?>"><label><span>Type your full name</span><input name="accepted_name" required maxlength="160" autocomplete="name"></label><label class="proposal-accept-check"><input type="checkbox" name="acceptance_confirmed" value="1" required><span>I approve this proposal and authorize North Mountain Media to proceed under these terms.</span></label><button type="submit">Accept proposal</button></form></div><div class="proposal-decline-panel"><span>Not ready to proceed?</span><h2>Decline or request changes.</h2><form method="post" action="<?=e(app_url('api/proposal-response.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="decline"><input type="hidden" name="token" value="<?=e($token)?>"><label><span>Reason or requested changes</span><textarea name="declined_reason" rows="5" maxlength="5000"></textarea></label><button type="submit">Decline proposal</button></form></div></section><?php elseif(in_array($proposal['status'],['accepted','converted'],true)):?><section class="proposal-response-complete is-accepted"><div>✓</div><h2>Proposal accepted</h2><p>Accepted by <?=e($proposal['accepted_name'])?> on <?=e(format_datetime($proposal['accepted_at']))?>.</p><?php if($proposal['payment_url']):?><a href="<?=e($proposal['payment_url'])?>" target="_blank" rel="noopener">Continue to deposit link ↗</a><?php endif;?></section><?php elseif($proposal['status']==='declined'):?><section class="proposal-response-complete is-declined"><div>×</div><h2>Proposal declined</h2><p>Your response has been recorded.</p></section><?php elseif($proposal['status']==='expired'):?><section class="proposal-response-complete is-declined"><div>!</div><h2>Proposal expired</h2><p>Contact North Mountain Media for an updated proposal.</p></section><?php endif;?></article><?php endif;?></main></section></div><script src="<?=e(app_url('assets/js/public-sidebar.js?v=20260728-content-controls-v62.1'))?>"></script><script src="<?=e(app_url('assets/js/public-music-shell.js?v=20260728-content-controls-v62.1'))?>"></script><script src="<?=e(app_url('assets/js/proposals.js?v=20260728-content-controls-v62.1'))?>"></script></body></html>
